create extension if not exists pgtap with schema extensions;
\i helpers/seed_members.sql
begin;
select plan(13);
select tests_seed_user('a5000000-0000-0000-0000-000000000041','p5-today@test.local','P5 today');
select tests_seed_group('a5000000-0000-0000-0000-000000000042','P5 today group','a5000000-0000-0000-0000-000000000041','Africa/Cairo','P5ABCDEL');
select tests_seed_group('a5000000-0000-0000-0000-000000000043','P5 today hizb','a5000000-0000-0000-0000-000000000041','Africa/Cairo','P5ABCDEM');
select tests_seed_group('a5000000-0000-0000-0000-000000000044','P5 archived','a5000000-0000-0000-0000-000000000041','Africa/Cairo','P5ABCDEN');
select tests_seed_group('a5000000-0000-0000-0000-000000000045','P5 today juz','a5000000-0000-0000-0000-000000000041','Africa/Cairo','P5ABCDF5');
select tests_seed_member('a5000000-0000-0000-0000-000000000042'::uuid,'a5000000-0000-0000-0000-000000000041'::uuid,1::smallint,'owner'::public.group_role);
select tests_seed_member('a5000000-0000-0000-0000-000000000043'::uuid,'a5000000-0000-0000-0000-000000000041'::uuid,1::smallint,'owner'::public.group_role);
select tests_seed_member('a5000000-0000-0000-0000-000000000044'::uuid,'a5000000-0000-0000-0000-000000000041'::uuid,1::smallint,'owner'::public.group_role);
select tests_seed_member('a5000000-0000-0000-0000-000000000045'::uuid,'a5000000-0000-0000-0000-000000000041'::uuid,1::smallint,'owner'::public.group_role);
update public.groups set status='active', start_juz=1, start_date=current_date, portion_unit='hizb' where id='a5000000-0000-0000-0000-000000000043';
update public.groups set status='active', start_juz=1, start_date=current_date, portion_unit='page' where id='a5000000-0000-0000-0000-000000000042';
update public.groups set status='active', start_juz=1, start_date=current_date where id='a5000000-0000-0000-0000-000000000045';
update public.groups set status='archived' where id='a5000000-0000-0000-0000-000000000044';
update public.profiles set main_group_id='a5000000-0000-0000-0000-000000000043' where id='a5000000-0000-0000-0000-000000000041';
select set_config('request.jwt.claims',json_build_object('sub','a5000000-0000-0000-0000-000000000041','role','authenticated')::text,true);
select is(jsonb_array_length(public.get_my_today()->'groups'),3,'archived membership is excluded from today feed');
select is((select value->>'status' from jsonb_array_elements(public.get_my_today()->'groups') where value->>'group_id'='a5000000-0000-0000-0000-000000000043'),'active','active group status is included');
select ok((select value->'day' ? 'cycle_number' and value->'day' ? 'cycle_day' and value->'day' ? 'cycle_length' from jsonb_array_elements(public.get_my_today()->'groups') where value->>'group_id'='a5000000-0000-0000-0000-000000000043'),'day contains cycle fields');
select is((select value->>'portion_unit' from jsonb_array_elements(public.get_my_today()->'groups') where value->>'group_id'='a5000000-0000-0000-0000-000000000043'),'hizb','group portion unit is included');
select ok((select value->'day' is not null and value->>'portion_unit'='juz' from jsonb_array_elements(public.get_my_today()->'groups') where value->>'group_id'='a5000000-0000-0000-0000-000000000045'),'juz group returns its day and portion unit');
select ok((select value->'day' ? 'completed_count' and value->'day' ? 'total_count' from jsonb_array_elements(public.get_my_today()->'groups') where value->>'group_id'='a5000000-0000-0000-0000-000000000043'),'day includes counts');
select is((select value->>'is_main' from jsonb_array_elements(public.get_my_today()->'groups') where value->>'group_id'='a5000000-0000-0000-0000-000000000043'),'true','pinned group is first and main');
select is((select value->>'group_id' from jsonb_array_elements(public.get_my_today()->'groups') with ordinality e(value,ord) where ord=1),'a5000000-0000-0000-0000-000000000043','main group orders first');
update public.assignments a set reader_membership_id=null,kind='unassigned',status='available' from public.group_days d where a.group_day_id=d.id and d.group_id='a5000000-0000-0000-0000-000000000042';
select ok((select value->'day'->>'rest_day'='true' from jsonb_array_elements(public.get_my_today()->'groups') where value->>'group_id'='a5000000-0000-0000-0000-000000000042'),'page group without caller assignments is a rest day');
select is((select jsonb_array_length(value->'items') from jsonb_array_elements(public.get_my_today()->'groups') where value->>'group_id'='a5000000-0000-0000-0000-000000000043'),1,'today includes caller''s own seat item');
update public.assignments a set kind='volunteer' from public.group_days d where a.group_day_id=d.id and d.group_id='a5000000-0000-0000-0000-000000000043' and a.reader_membership_id=(select id from public.group_memberships where group_id=d.group_id and user_id='a5000000-0000-0000-0000-000000000041');
select is(public.get_my_today()->'groups'->0->'items'->0->>'kind','volunteer','volunteer item is included for caller');
update public.assignments set kind='override',reader_membership_id=(select id from public.group_memberships where group_id='a5000000-0000-0000-0000-000000000043' and user_id='a5000000-0000-0000-0000-000000000041')
where id=(select a.id from public.assignments a join public.group_days d on d.id=a.group_day_id where d.group_id='a5000000-0000-0000-0000-000000000043' and a.reader_membership_id is null order by a.seat_number limit 1);
select ok((select jsonb_array_length(value->'items')=2 and value->'items' @> '[{"kind":"override"}]'::jsonb from jsonb_array_elements(public.get_my_today()->'groups') where value->>'group_id'='a5000000-0000-0000-0000-000000000043'),'override item is included for caller');
update public.groups set status='forming' where id='a5000000-0000-0000-0000-000000000043';
select is((select value->'day' from jsonb_array_elements(public.get_my_today()->'groups') where value->>'group_id'='a5000000-0000-0000-0000-000000000043'),'null'::jsonb,'forming group has null day');
select * from finish();
rollback;
